#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<long long, int>> heights(N);
    for (int i = 0; i < N; ++i) {
        cin >> heights[i].first;
        heights[i].second = i;
    }

    sort(heights.begin(), heights.end(), greater<>());

    vector<bool> active(N, false);
    int components = 0;
    int maxComponents = 0;

    for (int i = 0; i < N;) {
        int j = i;
        while (j < N && heights[j].first == heights[i].first) {
            int pos = heights[j].second;
            active[pos] = true;
            ++components;
            if (pos > 0 && active[pos - 1]) --components;
            if (pos + 1 < N && active[pos + 1]) --components;
            ++j;
        }

        maxComponents = max(maxComponents, components);
        i = j;
    }

    cout << maxComponents + 1 << '\n';
    return 0;
